function approxTimeForTick(tick) {
    // Ticks are 5-minute intervals starting 5:00am. Day boundaries reset the clock (per placement_schema.json's ticks_per_day).
    const dayStartTick = tick <= 225 ? 1 : (tick <= 450 ? 226 : 451);
    const minutesIn = (tick - dayStartTick) * 5;
    const hour = Math.floor(minutesIn / 60) + 5;
    const min = minutesIn % 60;
    const h12 = ((hour + 11) % 12) + 1;
    const ampm = hour >= 12 && hour < 24 ? 'pm' : (hour >= 24 ? 'am' : 'am');
    return `${h12}:${String(min).padStart(2,'0')}${hour >= 24 ? 'am (next day)' : (hour >= 12 ? 'pm' : 'am')}`;
  }

function timeForTick(tick) {
    const dayIdx = tick < DAY_BOUNDS[1] ? 0 : (tick < DAY_BOUNDS[2] ? 1 : 2);
    const dayStart = DAY_BOUNDS[dayIdx];
    const minutesIn = (tick - dayStart) * 5;
    const hour = Math.floor(minutesIn / 60) + 5;
    const min = minutesIn % 60;
    const h12 = ((hour + 11) % 12) + 1;
    const ampm = hour >= 12 ? 'PM' : 'AM';
    return `July ${dayIdx + 1}, ${h12}:${String(min).padStart(2, '0')} ${ampm}`;
  }

function hourForTick(tick) {
    const dayStartTick = tick <= 225 ? 1 : (tick <= 450 ? 226 : 451);
    const minutesIn = (tick - dayStartTick) * 5;
    return (Math.floor(minutesIn / 60) + 5) % 24; // ticks are 5-min intervals starting 5:00am each day
  }

function hourForTick(tick) {
    const dayStartTick = tick <= 225 ? 1 : (tick <= 450 ? 226 : 451);
    const minutesIn = (tick - dayStartTick) * 5;
    return (Math.floor(minutesIn / 60) + 5) % 24;
  }
